CUSTOM='<!doctype html><html lang="nl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Kies of ontwerp jouw stadion | Makers 3D Labs</title><link rel="stylesheet" href="assets/shop.css"><link rel="stylesheet" href="assets/categorie-paginas.css"><link rel="stylesheet" href="assets/stadion-maatwerk.css"></head><body>\n<header class="category-header"><div class="head-inner"><a href="index.html" aria-label="Makers 3D Labs — Home"><img src="makers3dlabs-logo.webp" alt="Makers 3D Labs" width="1600" height="500"></a><nav class="category-nav" aria-label="Hoofdnavigatie"><a href="index.html">Home</a><a href="winkel.html">Webshop</a></nav></div></header>\n<main class="category-main"><p><a href="categorie-voetbal.html">← Alle stadions</a></p><h1 class="category-title">Kies of ontwerp jouw stadion</h1><p class="category-intro">Kies een bestaand stadion dat nog niet in de collectie staat, een historische uitvoering of bedenk jouw eigen stadion. Beschrijf je idee en voeg foto’s, schetsen of een inspiratielink toe. Wij beoordelen de mogelijkheden en geven daarna een prijsvoorstel. Alle modellen worden volledig in kleur en met de hand afgewerkt.</p><form class="stadium-form" id="custom-stadium" method="post" enctype="multipart/form-data" action="https://formsubmit.co/alejandrojenniferbruna@gmail.com"><input type="hidden" name="_subject" value="Aanvraag eigen stadion — Makers 3D Labs"><input type="text" name="_honey" tabindex="-1" autocomplete="off" hidden><label for="customer">Naam *</label><input id="customer" name="Naam" required maxlength="150" autocomplete="name"><label for="email">E-mailadres *</label><input id="email" name="email" type="email" required autocomplete="email"><label for="phone">Telefoonnummer</label><input id="phone" name="Telefoon" type="tel" autocomplete="tel"><label for="request-type">Wat wil je aanvragen? *</label><select id="request-type" name="Soort stadionaanvraag" required><option value="">Maak een keuze</option><option>Een bestaand stadion</option><option>Een historische stadionuitvoering</option><option>Mijn eigen stadionontwerp</option></select><label for="stadium-name">Naam stadion of ontwerp *</label><input id="stadium-name" name="Stadion of ontwerp" required maxlength="180"><label for="club-location">Club, stad en land</label><input id="club-location" name="Club stad land" maxlength="250"><label for="stadium-era">Jaartal of gewenste uitvoering</label><input id="stadium-era" name="Jaartal uitvoering" maxlength="150" placeholder="Bijvoorbeeld huidige uitvoering of seizoen 1995"><label for="idea">Beschrijf jouw stadion en wensen *</label><textarea id="idea" name="Ontwerpwensen" required maxlength="10000" placeholder="Tribunes, dak, zitplaatsen, speelveld, lichtmasten, bijzondere details en alles wat je belangrijk vindt"></textarea><label for="custom-colors">Kleuren en afwerking</label><textarea id="custom-colors" name="Kleuren en afwerking" maxlength="3000" placeholder="Gewenste stadionkleuren, tribunekleuren en bijzondere details. Alleen volledig handgeschilderd in kleur."></textarea><label for="dimensions">Maten en gebruik</label><textarea id="dimensions" name="Afmetingen en gebruik" maxlength="3000" placeholder="Gewenste breedte, lengte en hoogte in cm; bijvoorbeeld 30–35 cm breed als decoratief displaymodel"></textarea><label for="custom-personal">Personalisatie</label><input id="custom-personal" name="Personalisatie" maxlength="300" placeholder="Naam, tekst of andere persoonlijke details"><label for="amount">Aantal *</label><input id="amount" name="Aantal" type="number" min="1" max="1000" value="1" required><label for="deadline">Gewenste datum</label><input id="deadline" name="Gewenste datum" type="date"><label for="reference">Link naar inspiratie</label><input id="reference" name="Inspiratielink" type="url" placeholder="https://"><label for="pictures">Voorbeeldafbeeldingen toevoegen</label><input id="pictures" name="attachment" type="file" accept="image/jpeg,image/png,image/webp" multiple><small>Maximaal 5 afbeeldingen (JPG, PNG of WebP), samen maximaal 9 MB.</small><p id="upload-error" role="alert"></p><div id="previews" class="stadium-preview"></div><label for="lighting-request">Verlichting</label><select id="lighting-request" name="Verlichting"><option>Geen verlichting</option><option>LED-sfeerverlichting op aanvraag</option><option>Uitgebreide verlichting op aanvraag</option><option>Graag advies</option></select><label for="budget">Gewenst budget (optioneel)</label><input id="budget" name="Budget" maxlength="120" placeholder="Bijvoorbeeld maximaal € 450"><label for="extra">Aanvullende wensen</label><textarea id="extra" name="Aanvullende wensen" maxlength="5000"></textarea><label><input type="checkbox" required> Ik geef toestemming om mijn gegevens en afbeeldingen te gebruiken om deze aanvraag te behandelen.</label><p><strong>Prijs op aanvraag.</strong> Je plaatst nog geen betaalde bestelling. Na ontvangst beoordelen we het ontwerp; je ontvangt daarna een prijsvoorstel.</p><button type="submit">Verstuur ontwerpaanvraag →</button></form><script src="assets/eigen-stadion.js"></script></main><script src="assets/shop-data.js"></script><script src="assets/shop.js"></script></body></html>\n'
UPLOAD="(()=>{const form=document.getElementById('custom-stadium'),input=document.getElementById('pictures'),error=document.getElementById('upload-error'),previews=document.getElementById('previews');let urls=[];function validate(){urls.forEach(URL.revokeObjectURL);urls=[];previews.replaceChildren();const files=Array.from(input.files);const message=files.length>5?'Kies maximaal 5 afbeeldingen.':files.some(f=>!['image/jpeg','image/png','image/webp'].includes(f.type))?'Gebruik alleen JPG, PNG of WebP.':files.reduce((n,f)=>n+f.size,0)>9*1024*1024?'De afbeeldingen mogen samen maximaal 9 MB zijn.':'';input.setCustomValidity(message);error.textContent=message;if(!message)files.forEach(file=>{const img=document.createElement('img');img.src=URL.createObjectURL(file);urls.push(img.src);img.alt=file.name;previews.append(img);});return !message;}input.addEventListener('change',validate);form.addEventListener('submit',e=>{if(!validate()){e.preventDefault();input.reportValidity();}});window.addEventListener('pagehide',()=>urls.forEach(URL.revokeObjectURL));})();\n"
CSS='\n.stadium-form{max-width:820px;margin:28px 0;padding:clamp(18px,4vw,34px);border:1px solid #65798c;border-radius:20px;background:#293747;color:#f4f7f9;display:grid;gap:10px}.stadium-form>label{font-weight:700;margin-top:10px}.stadium-form input:not([type=checkbox]),.stadium-form textarea,.stadium-form select{width:100%;font:inherit;border:1px solid #718595;border-radius:9px;background:#192733;color:#f4f7f9;padding:12px}.stadium-form textarea{min-height:95px;resize:vertical}.stadium-form button{font:inherit;font-weight:700;background:#9bd8de;color:#143039;border:0;border-radius:10px;padding:16px;cursor:pointer}.stadium-form :focus-visible{outline:3px solid #9bd8de;outline-offset:3px}.stadium-form small{color:#d2dce3}.stadium-preview{display:flex;gap:10px;flex-wrap:wrap}.stadium-preview img{width:100px;height:90px;object-fit:contain;background:#14212a;border-radius:7px}#upload-error{color:#ffb5ad}.stadium-form input[type=checkbox]{accent-color:#9bd8de}\n'

root=Path.cwd()
required=['voetbalstadion-deluxe.html','categorie-voetbal.html']+[m['image'] for m in MODELS]
missing=[n for n in required if not (root/n).is_file()]
if missing:raise SystemExit('Upload eerst de 5 WebP-bestanden en dit script; voer git pull uit. Ontbrekend: '+', '.join(missing))
template=(root/'voetbalstadion-deluxe.html').read_text(encoding='utf-8')
category=(root/'categorie-voetbal.html').read_text(encoding='utf-8')
if 'id="foreign-stadium-camp-nou"' in category:raise SystemExit('Buitenlandse stadions zijn al toegevoegd; niets gewijzigd.')
if 'stadiumBaseCents=36995' not in template or 'id="stadion-eigen-product"' not in template:raise SystemExit('Voeg eerst de Nederlandse stadionproducten toe; niets gewijzigd.')
if any((root/m['page']).exists() for m in MODELS) or (root/'ontwerp-eigen-stadion.html').exists():raise SystemExit('Een nieuwe pagina bestaat al; niets overschreven.')
marker='<div class="category-products" id="category-products">'
if marker not in category:raise SystemExit('Categorie niet herkend; niets gewijzigd.')
def euro(c):return '€ '+f'{c/100:.2f}'.replace('.',',')
files={};cards=[]
for m in MODELS:
 title=m['title'];esc=html.escape(title)
 page=template.replace('De Kuip — Feyenoord',esc).replace('stadion-feyenoord-de-kuip-voorbeeld.webp',m['image'])
 page=page.replace('stadiumBaseCents=36995','stadiumBaseCents='+str(m['price'])).replace('€ 369,95',euro(m['price']))
 page=page.replace('const stadiumProduct="'+esc+'"','const stadiumProduct='+json.dumps(title+' — '+m['city']+' — '+m['edition'],ensure_ascii=False))
 page=page.replace('<div class="price">Vanaf','<p class="product-info">'+html.escape(m['city'])+' · '+html.escape(m['edition'])+'</p><div class="price">Vanaf',1)
 page=page.replace('AI-voorbeeldafbeelding van dit stadion; details kunnen afwijken.','AI-voorbeeldafbeelding: '+html.escape(m['edition'])+'. Details kunnen afwijken.')
 files[m['page']]=page
 cards.append('<article id="foreign-stadium-'+m['slug']+'" class="category-product" data-name="'+esc+' '+html.escape(m['city']+' '+m['edition'])+'" data-colors="[&quot;Meerkleurig&quot;]" data-kind="Buitenlandse stadions" data-price="'+str(m['price'])+'" data-personal="true"><a class="category-product-photo" href="'+m['page']+'"><img src="'+m['image']+'" alt="'+esc+' — AI-voorbeeldmodel" loading="lazy"></a><div class="category-product-body"><span class="category-product-type">Handgeschilderd stadionmodel</span><h2>'+esc+'</h2><p>'+html.escape(m['edition'])+'</p><strong class="category-price">Vanaf '+euro(m['price'])+'</strong><a class="category-product-link" href="'+m['page']+'">Bekijk en personaliseer →</a></div></article>')
customcard='<article id="custom-stadium-product" class="category-product" data-name="Kies jouw eigen stadion Ontwerp zelf stadion Foto schets maatwerk" data-colors="[&quot;Meerkleurig&quot;,&quot;Op aanvraag&quot;]" data-kind="Stadion op maat" data-price="" data-personal="true"><a class="category-product-photo" href="ontwerp-eigen-stadion.html" style="display:grid;place-items:center;min-height:220px;background:#172932;text-decoration:none"><span style="text-align:center;font-size:26px;color:#9bd8de">⚽<br>Jouw stadion<br><small>Jouw idee, persoonlijk gemaakt</small></span></a><div class="category-product-body"><span class="category-product-type">Eigen stadion of ontwerp</span><h2>Kies of ontwerp jouw stadion</h2><p>Bestaand, historisch of zelf bedacht. Stuur foto’s, schetsen en jouw wensen mee.</p><strong class="category-price">Prijs op aanvraag</strong><a class="category-product-link" href="ontwerp-eigen-stadion.html">Stuur jouw idee en foto’s →</a></div></article>'
category=category.replace(marker,marker+customcard+''.join(cards),1)
extra='<label class="filter-check"><input type="checkbox" name="kind" value="Buitenlandse stadions"><span>Buitenlandse stadions</span></label><label class="filter-check"><input type="checkbox" name="kind" value="Stadion op maat"><span>Stadion op maat</span></label>'
category,n=re.subn(r'(<fieldset class="filter-group"><legend>Productsoort</legend>.*?)(</fieldset>)',lambda x:x[1]+extra+x[2],category,count=1,flags=re.S)
if n!=1:raise SystemExit('Productfilters niet herkend; niets geschreven.')
category=category.replace('<span>Stadionmodellen</span>','<span>Nederlandse stadions</span>')
count=len(re.findall(r'<article\b[^>]*class="category-product"',category))
category=re.sub(r'(<p id="category-count"[^>]*>).*?(</p>)',lambda x:x[1]+str(count)+' producten'+x[2],category,count=1,flags=re.S)
category=category.replace('href="contact.html?product=3D%20Voetbalstadion%20Deluxe#quoteForm">Vraag jouw stadion aan','href="ontwerp-eigen-stadion.html">Vraag jouw stadion aan')
files.update({'categorie-voetbal.html':category,'ontwerp-eigen-stadion.html':CUSTOM,'assets/eigen-stadion.js':UPLOAD,'assets/stadion-maatwerk.css':CSS})
stamp=datetime.datetime.now().strftime('%Y%m%d-%H%M%S')
for name,content in files.items():
 p=root/name
 if p.exists():
  backup=root/'backups'/('buitenlandse-stadions-'+stamp)/name;backup.parent.mkdir(parents=True,exist_ok=True);backup.write_bytes(p.read_bytes())
 p.parent.mkdir(parents=True,exist_ok=True);p.write_text(content,encoding='utf-8')
print('Klaar: 5 buitenlandse stadionproducten en eigen-stadionformulier met foto-upload toegevoegd. Nog niet gepubliceerd.')
